<main class="page__body"><!--[--><!--[--><div class="hero hero--loaded" style="--bg-enter-delay:2.6s;"><div class="hero__bg"><img width="1920" height="1236" data-nuxt-img="" sizes="(max-width: 639px) 200vw, (max-width: 1279px) 100vw, (max-width: 1349px) 100vw, 1920px" srcset="/assets/img/36c6b49b4eda-hygiene-hero-bg.avif 640w, /assets/img/2bfb60253f61-hygiene-hero-bg.avif 1280w, /assets/img/51d38ed388ce-hygiene-hero-bg.avif 1920w, /assets/img/738f316f3b42-hygiene-hero-bg.avif 2560w, /assets/img/756fabdb200a-hygiene-hero-bg.avif 3840w" onerror="this.setAttribute('data-error', 1)" class="image image--loaded hero__image" alt="" fetchpriority="high" src="/assets/img/756fabdb200a-hygiene-hero-bg.avif"></div><div class="hero__content"><div class="container container--size-default"><!--[--><div class="hero-content-grid"><div class="hero-content-grid__item hero-content-grid__item--header"><h1 class="hero__title u-text-headings-medium" style="max-width: 381px;"><span class="word" aria-hidden="true" style="display: inline-block;">Vesela</span> <span class="word" aria-hidden="true" style="display: inline-block;">smaida</span> <span class="word" aria-hidden="true" style="display: inline-block;">noslēpums</span> <span class="word" aria-hidden="true" style="display: inline-block;">ir</span> <span class="word" aria-hidden="true" style="display: inline-block;">regulāras</span> <span class="word" aria-hidden="true" style="display: inline-block;">vizītes</span> <span class="word" aria-hidden="true" style="display: inline-block;">pie</span> <span class="word" aria-hidden="true" style="display: inline-block;">higiēnista.</span><span class="sr-only" style="position: absolute; width: 1px; height: 1px; padding: 0px; margin: -1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px;">Vesela smaida noslēpums ir regulāras vizītes pie higiēnista.</span></h1></div><div class="hero-content-grid__item hero-content-grid__item--body"><div class="video-dialog video-di